#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    stringstream ss(line);
    int R, C;
    ss >> R >> C;
    if (R > C) {
        int temp = R;
        R = C;
        C = temp;
    }
    int max_mask = 1 << R;
    vector<vector<vector<int>>> dp(C + 1, vector<vector<int>>(max_mask, vector<int>(max_mask, 69)));
    for (int m = 0; m < max_mask; m++) {
        dp[0][0][m] = 0;
    }
    for (int colIdx = 1; colIdx <= C; colIdx++) {
        for (int prevMask = 0; prevMask < max_mask; prevMask++) {
            for (int currMask = 0; currMask < max_mask; currMask++) {
                for (int nextMask = 0; nextMask < max_mask; nextMask++) {
                    bool valid = true;
                    for (int b = 0; b < R; b++) {
                        if ((currMask & (1 << b)) == 0) {
                            bool neighbor = false;
                            if (b > 0 && (currMask & (1 << (b - 1))) != 0) neighbor = true;
                            if (b + 1 < R && (currMask & (1 << (b + 1))) != 0) neighbor = true;
                            if ((prevMask & (1 << b)) != 0) neighbor = true;
                            if ((nextMask & (1 << b)) != 0) neighbor = true;
                            if (!neighbor) {
                                valid = false;
                                break;
                            }
                        }
                    }
                    if (valid) {
                        dp[colIdx][currMask][nextMask] = min(dp[colIdx][currMask][nextMask], dp[colIdx - 1][prevMask][currMask] + __builtin_popcount(prevMask));
                    }
                }
            }
        }
    }
    int maxUnspiders = 0;
    for (int m = 0; m < max_mask; m++) {
        maxUnspiders = max(maxUnspiders, R * C - (dp[C][m][0] + __builtin_popcount(m)));
    }
    cout << maxUnspiders << "\n";
    return 0;
}
